{"path": "/tmp/sv-21e55b10855f478184639ba08aab39fe/Components/Pages/Board/KanbanColumn.razor", "file_text": "<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body overflow-auto" style="max-height: 60vh;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="ColumnIndex > 0"
                          CanMoveRight="ColumnIndex < 2"
                          OnMoveLeft="() => MoveLeft(task)"
                          OnMoveRight="() => MoveRight(task)" />
            }

            @if (showForm)
            {
                <AddTaskForm OnSave="HandleSave" OnCancel="() => showForm = false" />
            }
            else
            {
                <button class="btn btn-sm btn-outline-primary w-100 mt-2" @onclick="() => showForm = true">+ Add Task</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = string.Empty;
    [Parameter, EditorRequired] public int ColumnIndex { get; set; }
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter, EditorRequired] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate, string Status)> OnAddTask { get; set; }

    private bool showForm;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    private async Task MoveLeft(TaskItem task)
    {
        if (ColumnIndex > 0)
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex - 1]));
    }

    private async Task MoveRight(TaskItem task)
    {
        if (ColumnIndex < 2)
            await OnMoveTask.InvokeAsync((task.Id, Statuses[ColumnIndex + 1]));
    }

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnAddTask.InvokeAsync((formData.Title, formData.Assignee, formData.Priority, formData.DueDate, ColumnName));
        showForm = false;
    }
}
"}

